cssContent:
/* Kumori paper theme for Boomi Flow (2026-10-05) */
:root { --kumori-paper:#f5f5f4; --kumori-cream:#efe9dd; --kumori-ink:#1b1b1a; --kumori-amber:#e8a33a; }
body, .flow, .mw-bs { background: var(--kumori-paper) !important; color: var(--kumori-ink);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; }
h1, h2, h3, .page-title { color: var(--kumori-ink); font-weight: 600; letter-spacing: -0.01em; }
a { color: var(--kumori-ink); text-decoration-color: var(--kumori-amber); }
.btn, button, .outcome { background: var(--kumori-ink) !important; color: var(--kumori-paper) !important;
  border: 1px solid var(--kumori-ink) !important; border-radius: 8px !important; }
.btn:hover, button:hover, .outcome:hover { background: var(--kumori-amber) !important; color: var(--kumori-ink) !important; }
table, .table { background: var(--kumori-cream); border-radius: 10px; border-collapse: separate; overflow: hidden; }
th { background: var(--kumori-ink); color: var(--kumori-paper); font-weight: 600; }
td, th { padding: 10px 14px !important; border-color: rgba(27,27,26,0.12) !important; }
